-- Tenant-admin observer v2. Stop and fully drain all pre-0063 writers before independent migration.

-- Forward-only: partial DDL or marker loss is rejected; never repair or replay DDL automatically.

-- No network, secret backfill, external deletion or completion is authorized.

SET @tenant_webhook_previous_gcml=@@SESSION.group_concat_max_len;

SET SESSION group_concat_max_len=1048576;

SET @tenant_webhook_marker_ok=(SELECT COUNT(*)=1 FROM schema_migrations WHERE BINARY name=BINARY '0062_mcp_registry.sql');

SET @tenant_webhook_predecessor_ok=(
  (SELECT COUNT(*)=8 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%')
  AND (SELECT COUNT(*)=0 FROM information_schema.partitions WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%' AND partition_name IS NOT NULL)
  AND (SELECT COUNT(*)=795 AND SUM(trigger_name LIKE 'trg_mcp_registry_%')=32 AND SUM(OCTET_LENGTH(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4','')))))+COUNT(*)-1<=@@SESSION.group_concat_max_len FROM information_schema.triggers WHERE trigger_schema=DATABASE())
  AND SHA2(CONCAT_WS('::',
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,engine,table_collation,row_format,create_options) ORDER BY table_name SEPARATOR '|'),256) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,LPAD(ordinal_position,3,'0'),column_name,column_type,is_nullable,IFNULL(column_default,'<NULL>'),extra,IFNULL(character_set_name,'-'),IFNULL(collation_name,'-'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(IFNULL(generation_expression,''),'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY table_name,ordinal_position SEPARATOR '|'),256) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,index_name,LPAD(seq_in_index,3,'0'),column_name,non_unique,index_type,IFNULL(collation,'-'),IFNULL(sub_part,'-'),IFNULL(nullable,'-')) ORDER BY table_name,index_name,seq_in_index SEPARATOR '|'),256) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,constraint_type,IFNULL(enforced,'-')) ORDER BY table_name,constraint_name SEPARATOR '|'),256) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',constraint_name,LOWER(REPLACE(REPLACE(REGEXP_REPLACE(check_clause,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY constraint_name SEPARATOR '|'),256) FROM information_schema.check_constraints WHERE constraint_schema=DATABASE() AND constraint_name='chk_mcp_owner'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,referenced_table_name,update_rule,delete_rule) ORDER BY table_name,constraint_name SEPARATOR '|'),256) FROM information_schema.referential_constraints WHERE constraint_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,LPAD(ordinal_position,3,'0'),column_name,referenced_table_name,referenced_column_name) ORDER BY table_name,constraint_name,ordinal_position SEPARATOR '|'),256) FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%' AND referenced_table_name IS NOT NULL),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY event_object_table,trigger_name SEPARATOR '|'),256) FROM information_schema.triggers WHERE trigger_schema=DATABASE())
  ),256)='ffb2fae1db46f5b26b43579623d0dc29b6afd64b060ed53ae82ca2fc04b12a01'
);

SET @migration_sql=IF(@tenant_webhook_predecessor_ok=1 AND @tenant_webhook_marker_ok=1,'SELECT 1','SELECT 1 FROM __invalid_tenant_webhook_predecessor__');

PREPARE migration_stmt FROM @migration_sql;

EXECUTE migration_stmt;

DEALLOCATE PREPARE migration_stmt;



CREATE TABLE tenant_webhook_slots (
  webhook_id CHAR(64) NOT NULL,tenant_id VARCHAR(128) NOT NULL,name VARCHAR(64) NOT NULL,state VARCHAR(32) NOT NULL,record_json JSON NULL,
  PRIMARY KEY(webhook_id),UNIQUE KEY uk_tenant_webhook_name(tenant_id,name),KEY idx_tenant_webhook_state(tenant_id,state,webhook_id),
  CONSTRAINT chk_tenant_webhook_slot_state CHECK(state IN ('enabled','disabled','deleted'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE tenant_webhook_versions (
  config_version_id CHAR(64) NOT NULL,webhook_id CHAR(64) NOT NULL,tenant_id VARCHAR(128) NOT NULL,record_json JSON NOT NULL,
  PRIMARY KEY(config_version_id),KEY idx_th_versions_owner(webhook_id,config_version_id),
  CONSTRAINT fk_th_versions_slot FOREIGN KEY(webhook_id) REFERENCES tenant_webhook_slots(webhook_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE tenant_webhook_replays (
  key_sha256 CHAR(64) NOT NULL,webhook_id CHAR(64) NOT NULL,tenant_id VARCHAR(128) NOT NULL,record_json JSON NOT NULL,
  PRIMARY KEY(key_sha256),KEY idx_th_replays_owner(webhook_id,key_sha256),
  CONSTRAINT fk_th_replays_slot FOREIGN KEY(webhook_id) REFERENCES tenant_webhook_slots(webhook_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE tenant_webhook_snapshots (
  snapshot_id CHAR(64) NOT NULL,webhook_id CHAR(64) NOT NULL,tenant_id VARCHAR(128) NOT NULL,record_json JSON NOT NULL,call_item_id VARCHAR(64) NOT NULL,subject_user_id VARCHAR(128) NOT NULL,session_id VARCHAR(64) NOT NULL,turn_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(snapshot_id),KEY idx_th_snapshots_owner(webhook_id,snapshot_id),KEY idx_th_snapshots_call(webhook_id,call_item_id,snapshot_id),KEY idx_th_snapshots_tenant(tenant_id,call_item_id,snapshot_id),
  CONSTRAINT fk_th_snapshots_slot FOREIGN KEY(webhook_id) REFERENCES tenant_webhook_slots(webhook_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE tenant_webhook_intents (
  intent_id CHAR(64) NOT NULL,webhook_id CHAR(64) NOT NULL,tenant_id VARCHAR(128) NOT NULL,record_json JSON NOT NULL,call_item_id VARCHAR(64) NOT NULL,subject_user_id VARCHAR(128) NOT NULL,session_id VARCHAR(64) NOT NULL,turn_id VARCHAR(64) NOT NULL,state VARCHAR(32) NOT NULL,
  PRIMARY KEY(intent_id),KEY idx_th_intents_owner(webhook_id,intent_id),KEY idx_th_intents_call(webhook_id,call_item_id,intent_id),KEY idx_th_intents_tenant(tenant_id,call_item_id,intent_id),KEY idx_th_intent_state(state,intent_id),
  CONSTRAINT fk_th_intents_slot FOREIGN KEY(webhook_id) REFERENCES tenant_webhook_slots(webhook_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE tenant_webhook_milestones (
  milestone_id CHAR(64) NOT NULL,webhook_id CHAR(64) NOT NULL,tenant_id VARCHAR(128) NOT NULL,record_json JSON NOT NULL,call_item_id VARCHAR(64) NOT NULL,subject_user_id VARCHAR(128) NOT NULL,session_id VARCHAR(64) NOT NULL,turn_id VARCHAR(64) NOT NULL,kind VARCHAR(16) NOT NULL,config_version_id CHAR(64) NOT NULL,started_at_ms BIGINT NULL,
  PRIMARY KEY(milestone_id),KEY idx_th_milestones_owner(webhook_id,milestone_id),KEY idx_th_milestones_call(webhook_id,call_item_id,milestone_id),KEY idx_th_milestones_tenant(tenant_id,call_item_id,milestone_id),UNIQUE KEY uk_th_milestone_call(webhook_id,call_item_id,kind),
  CONSTRAINT fk_th_milestones_slot FOREIGN KEY(webhook_id) REFERENCES tenant_webhook_slots(webhook_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TRIGGER trg_tenant_webhook_slots_bi BEFORE INSERT ON tenant_webhook_slots FOR EACH ROW BEGIN IF (NEW.record_json IS NULL AND NEW.state='disabled' AND EXISTS(SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.tenant_id AND BINARY t.tenant_id=BINARY NEW.tenant_id AND BINARY t.subject_id=BINARY NEW.tenant_id AND t.state='active' FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.tenant_id AND BINARY a.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.tenant_id AND BINARY r.tenant_id=BINARY NEW.tenant_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tenant webhook evidence is invalid'; END IF; END;

CREATE TRIGGER trg_tenant_webhook_slots_bu BEFORE UPDATE ON tenant_webhook_slots FOR EACH ROW BEGIN IF (BINARY NEW.webhook_id=BINARY OLD.webhook_id AND BINARY NEW.tenant_id=BINARY OLD.tenant_id AND BINARY NEW.name=BINARY OLD.name AND NEW.record_json IS NOT NULL AND BINARY NEW.webhook_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.webhookId')) AND BINARY NEW.tenant_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.tenantId')) AND BINARY NEW.name=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.name')) AND BINARY NEW.state=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state')) AND JSON_EXTRACT(NEW.record_json,'$.revision')=COALESCE(JSON_EXTRACT(OLD.record_json,'$.revision'),0)+1 AND JSON_EXTRACT(NEW.record_json,'$.generation')=COALESCE(JSON_EXTRACT(OLD.record_json,'$.generation'),1)+IF(OLD.state='deleted',1,0) AND (NEW.state='deleted' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.currentVersionId'))='NULL' OR NEW.state IN ('enabled','disabled') AND EXISTS(SELECT 1 FROM tenant_webhook_versions v WHERE v.config_version_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.currentVersionId')) AND BINARY v.config_version_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.currentVersionId')) AND v.webhook_id=NEW.webhook_id AND BINARY v.webhook_id=BINARY NEW.webhook_id FOR SHARE)) AND EXISTS(SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.tenant_id AND BINARY t.tenant_id=BINARY NEW.tenant_id AND BINARY t.subject_id=BINARY NEW.tenant_id AND t.state='active' FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.tenant_id AND BINARY a.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.tenant_id AND BINARY r.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND (OLD.record_json IS NULL OR JSON_EXTRACT(NEW.record_json,'$.createdAtMs')=JSON_EXTRACT(OLD.record_json,'$.createdAtMs')) AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.updatedAtMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.record_json,'$.updatedAtMs')>=CAST('0' AS JSON) AND (OLD.record_json IS NULL OR (JSON_TYPE(JSON_EXTRACT(OLD.record_json,'$.updatedAtMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.record_json,'$.updatedAtMs')>=JSON_EXTRACT(OLD.record_json,'$.updatedAtMs'))) AND JSON_EXTRACT(NEW.record_json,'$.updatedAtMs')>=JSON_EXTRACT(NEW.record_json,'$.createdAtMs')) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tenant webhook row is immutable'; END IF; END;

