CREATE TRIGGER trg_tenant_webhook_versions_bi BEFORE INSERT ON tenant_webhook_versions FOR EACH ROW BEGIN IF (BINARY NEW.config_version_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND BINARY NEW.webhook_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.webhookId')) AND BINARY NEW.tenant_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.tenantId')) AND BINARY NEW.tenant_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.tenantId')) AND JSON_EXTRACT(NEW.record_json,'$.revision')>0 AND JSON_EXTRACT(NEW.record_json,'$.generation')>0 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.keyVersionId'))=BINARY NEW.config_version_id AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.config.phase')) IN ('preToolUse','postToolUse') AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.config.bodyScopes'))='ARRAY' AND JSON_LENGTH(JSON_EXTRACT(NEW.record_json,'$.config.bodyScopes'))<=3 AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.signingKey.profile'))='tenant-webhook-aes-256-gcm-v2' AND OCTET_LENGTH(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.signingKey.ciphertext'))))=32 AND EXISTS(SELECT 1 FROM tenant_webhook_slots s WHERE s.webhook_id=NEW.webhook_id AND BINARY s.webhook_id=BINARY NEW.webhook_id AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.name=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.name')) AND (s.record_json IS NULL AND JSON_EXTRACT(NEW.record_json,'$.revision')=1 AND JSON_EXTRACT(NEW.record_json,'$.generation')=1 OR s.record_json IS NOT NULL AND JSON_EXTRACT(NEW.record_json,'$.revision')=JSON_EXTRACT(s.record_json,'$.revision')+1 AND JSON_EXTRACT(NEW.record_json,'$.generation')=JSON_EXTRACT(s.record_json,'$.generation')+IF(s.state='deleted',1,0)) FOR SHARE) AND EXISTS(SELECT 1 FROM api_keys a WHERE a.tenant_id=NEW.tenant_id AND a.key_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.adminApiKeyId')) AND BINARY a.tenant_id=BINARY NEW.tenant_id AND BINARY a.key_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.adminApiKeyId')) AND a.revoked_at_ms IS NULL AND JSON_CONTAINS(a.scopes,JSON_QUOTE('admin')) FOR SHARE) AND ((JSON_LENGTH(JSON_EXTRACT(NEW.record_json,'$.config.bodyScopes'))=0 AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.disclosureSha256'))='NULL') OR (JSON_LENGTH(JSON_EXTRACT(NEW.record_json,'$.config.bodyScopes'))>0 AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.disclosureSha256')) REGEXP '^[a-f0-9]{64}$')) AND EXISTS(SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.tenant_id AND BINARY t.tenant_id=BINARY NEW.tenant_id AND BINARY t.subject_id=BINARY NEW.tenant_id AND t.state='active' FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.tenant_id AND BINARY a.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.tenant_id AND BINARY r.tenant_id=BINARY NEW.tenant_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tenant webhook evidence is invalid'; END IF; END;

