CREATE TRIGGER trg_tenant_webhook_snapshots_bi BEFORE INSERT ON tenant_webhook_snapshots FOR EACH ROW BEGIN IF (BINARY NEW.snapshot_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.snapshotId')) AND BINARY NEW.webhook_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.webhookId')) AND BINARY NEW.call_item_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.callItemId')) AND BINARY NEW.session_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.sessionId')) AND BINARY NEW.turn_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.turnId')) AND BINARY NEW.tenant_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.tenantId')) AND BINARY NEW.subject_user_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.userId')) AND EXISTS(SELECT 1 FROM sessions s JOIN turns t ON t.turn_id=NEW.turn_id AND t.session_id=s.session_id AND BINARY t.turn_id=BINARY NEW.turn_id AND BINARY t.session_id=BINARY s.session_id WHERE s.session_id=NEW.session_id AND BINARY s.session_id=BINARY NEW.session_id AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.subject_user_id AND s.deleted_at_ms IS NULL AND s.last_seq>=JSON_EXTRACT(NEW.record_json,'$.throughSeq') AND s.fence_token=JSON_EXTRACT(NEW.record_json,'$.fence') FOR SHARE) AND EXISTS(SELECT 1 FROM tenant_webhook_versions v WHERE v.config_version_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND BINARY v.config_version_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND v.webhook_id=NEW.webhook_id AND BINARY v.webhook_id=BINARY NEW.webhook_id AND JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.phase'))='postToolUse' FOR SHARE) AND EXISTS(SELECT 1 FROM items i WHERE i.item_id=NEW.call_item_id AND BINARY i.item_id=BINARY NEW.call_item_id AND i.session_id=NEW.session_id AND BINARY i.session_id=BINARY NEW.session_id AND i.turn_id=NEW.turn_id AND BINARY i.turn_id=BINARY NEW.turn_id AND i.type='toolCall' FOR SHARE) AND EXISTS(SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.tenant_id AND BINARY t.tenant_id=BINARY NEW.tenant_id AND BINARY t.subject_id=BINARY NEW.tenant_id AND t.state='active' FOR SHARE) AND EXISTS(SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.subject_user_id AND BINARY u.tenant_id=BINARY NEW.tenant_id AND BINARY u.subject_id=BINARY NEW.subject_user_id AND u.state='active' FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.tenant_id AND BINARY a.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.tenant_id AND BINARY r.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND ((JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.availability'))='available' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.envelope.profile'))='tenant-webhook-aes-256-gcm-v2' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.plaintextSha256')) REGEXP '^[a-f0-9]{64}$') OR (JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.availability'))='unavailable' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.envelope'))='NULL' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.plaintextSha256'))='NULL'))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tenant webhook evidence is invalid'; END IF; END;

