son,'$.payloadBytes'))='NULL' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.invocationId'))='NULL' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.claimTokenSha256'))='NULL' AND JSON_EXTRACT(NEW.record_json,'$.completedAtMs') IS NOT NULL)) AND JSON_EXTRACT(NEW.record_json,'$.preparedDeadlineAtMs')>JSON_EXTRACT(NEW.record_json,'$.createdAtMs') AND EXISTS(SELECT 1 FROM tenant_webhook_versions v WHERE v.config_version_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND BINARY v.config_version_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND v.webhook_id=NEW.webhook_id AND BINARY v.webhook_id=BINARY NEW.webhook_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.phase'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.phase')) FOR SHARE) AND EXISTS(SELECT 1 FROM tenant_webhook_milestones m WHERE m.webhook_id=NEW.webhook_id AND m.call_item_id=NEW.call_item_id AND m.kind=IF(JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.phase'))='preToolUse','pre','post') AND BINARY m.webhook_id=BINARY NEW.webhook_id AND BINARY m.call_item_id=BINARY NEW.call_item_id AND BINARY m.config_version_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) FOR SHARE) AND (JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.phase'))='preToolUse' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.resultItemId'))='NULL' OR JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.phase'))='postToolUse' AND EXISTS(SELECT 1 FROM tenant_webhook_snapshots p WHERE p.webhook_id=NEW.webhook_id AND p.call_item_id=NEW.call_item_id AND BINARY p.webhook_id=BINARY NEW.webhook_id AND BINARY p.call_item_id=BINARY NEW.call_item_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(p.record_json,'$.configVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) FOR SHARE) AND EXISTS(SELECT 1 FROM items i JOIN items c ON c.item_id=NEW.call_item_id AND BINARY c.item_id=BINARY NEW.call_item_id WHERE i.item_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.resultItemId')) AND BINARY i.item_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.resultItemId')) AND i.session_id=NEW.session_id AND BINARY i.session_id=BINARY NEW.session_id AND i.turn_id=NEW.turn_id AND BINARY i.turn_id=BINARY NEW.turn_id AND i.type='toolResult' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(i.body,'$.toolCallId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(c.body,'$.toolCallId')) FOR SHARE)) AND EXISTS(SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.tenant_id AND BINARY t.tenant_id=BINARY NEW.tenant_id AND BINARY t.subject_id=BINARY NEW.tenant_id AND t.state='active' FOR SHARE) AND EXISTS(SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.subject_user_id AND BINARY u.tenant_id=BINARY NEW.tenant_id AND BINARY u.subject_id=BINARY NEW.subject_user_id AND u.state='active' FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.tenant_id AND BINARY a.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.tenant_id AND BINARY r.tenant_id=BINARY NEW.tenant_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tenant webhook evidence is invalid'; END IF; END;

CREATE TRIGGER trg_tenant_webhook_intents_bu BEFORE UPDATE ON tenant_webhook_intents FOR EACH ROW BEGIN IF ((BINARY NEW.intent_id=BINARY OLD.intent_id AND BINARY NEW.webhook_id=BINARY OLD.webhook_id AND BINARY NEW.tenant_id=BINARY OLD.tenant_id AND BINARY NEW.subject_user_id=BINARY OLD.subject_user_id AND BINARY NEW.session_id=BINARY OLD.session_id AND BINARY NEW.turn_id=BINARY OLD.turn_id AND BINARY NEW.call_item_id=BINARY OLD.call_item_id AND CAST(JSON_REMOVE(NEW.record_json,'$.state','$.claimTokenSha256','$.sendDeadlineAtMs','$.resultSha256','$.completedAtMs','$.finishRequestSha256') AS BINARY)=CAST(JSON_REMOVE(OLD.record_json,'$.state','$.claimTokenSha256','$.sendDeadlineAtMs','$.resultSha256','$.completedAtMs','$.finishRequestSha256') AS BINARY) AND BINARY NEW.state=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state')) AND (OLD.state='prepared' AND NEW.state IN ('sending','failed_not_dispatched','blocked') OR OLD.state='sending' AND NEW.state IN ('acknowledged','failed_not_dispatched','outcome_unknown')) AND (NEW.state<>'sending' OR JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.claimTokenSha256'))='STRING' AND JSON_EXTRACT(NEW.record_json,'$.sendDeadlineAtMs')>JSON_EXTRACT(NEW.record_json,'$.createdAtMs') AND EXISTS(SELECT 1 FROM sessions s JOIN turns t ON t.turn_id=NEW.turn_id AND t.session_id=s.session_id AND BINARY t.turn_id=BINARY NEW.turn_id AND BINARY t.session_id=BINARY s.session_id WHERE s.session_id=NEW.session_id AND BINARY s.session_id=BINARY NEW.session_id AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.subject_user_id AND s.deleted_at_ms IS NULL AND s.fence_token=JSON_EXTRACT(NEW.record_json,'$.fence') FOR SHARE) AND EXISTS(SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.tenant_id AND BINARY t.tenant_id=BINARY NEW.tenant_id AND BINARY t.subject_id=BINARY NEW.tenant_id AND t.state='active' FOR SHARE) AND EXISTS(SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.subject_user_id AND BINARY u.tenant_id=BINARY NEW.tenant_id AND BINARY u.subject_id=BINARY NEW.subject_user_id AND u.state='active' FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.tenant_id AND BINARY a.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.tenant_id AND BINARY r.tenant_id=BINARY NEW.tenant_id FOR SHARE)) AND (NEW.state<>'sending' OR (CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)<JSON_EXTRACT(NEW.record_json,'$.preparedDeadlineAtMs') AND EXISTS(SELECT 1 FROM tenant_webhook_slots w WHERE w.webhook_id=NEW.webhook_id AND BINARY w.webhook_id=BINARY NEW.webhook_id AND w.state='enabled' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(w.record_json,'$.currentVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND JSON_EXTRACT(w.record_json,'$.revision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_EXTRACT(w.record_json,'$.generation')=JSON_EXTRACT(NEW.record_json,'$.generation') FOR SHARE)))) OR (OLD.state='outcome_unknown' AND NEW.state='outcome_unknown' AND JSON_TYPE(JSON_EXTRACT(OLD.record_json,'$.finishRequestSha256'))='NULL' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.finishRequestSha256')) REGEXP '^[a-f0-9]{64}$' AND BINARY NEW.intent_id=BINARY OLD.intent_id AND BINARY NEW.webhook_id=BINARY OLD.webhook_id AND BINARY NEW.tenant_id=BINARY OLD.tenant_id AND BINARY NEW.subject_user_id=BINARY OLD.subject_user_id AND BINARY NEW.session_id=BINARY OLD.session_id AND BINARY NEW.turn_id=BINARY OLD.turn_id AND BINARY NEW.call_item_id=BINARY OLD.call_item_id AND CAST(JSON_REMOVE(NEW.record_json,'$.finishRequestSha256') AS BINARY)=CAST(JSON_REMOVE(OLD.record_json,'$.finishRequestSha256') AS BINARY))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tenant webhook row is immutable'; END IF; END;

