W.turn_id AND i.type='toolCall' FOR SHARE) AND EXISTS(SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.tenant_id AND BINARY t.tenant_id=BINARY NEW.tenant_id AND BINARY t.subject_id=BINARY NEW.tenant_id AND t.state='active' FOR SHARE) AND EXISTS(SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.subject_user_id AND BINARY u.tenant_id=BINARY NEW.tenant_id AND BINARY u.subject_id=BINARY NEW.subject_user_id AND u.state='active' FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.tenant_id AND BINARY a.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS(SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.tenant_id AND BINARY r.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND (NEW.kind<>'post' OR JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.resultItemId'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.canonicalPayloadSha256')) REGEXP '^[a-f0-9]{64}$' AND JSON_EXTRACT(NEW.record_json,'$.canonicalPayloadBytes')>0)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tenant webhook evidence is invalid'; END IF; END;

